mapper.select:


    t.del_flag = '0'
    and w.del_flag = '0'
    and t.task_status = #{taskStatus}
    and w.warning_type = #{warningType}
    and t.dept_id = #{deptId}
    and t.assignee_user_id = #{assigneeUserId}

        and t.dispatch_time >= #{params.beginDispatchTime}


        and t.dispatch_time <= #{params.endDispatchTime}


        and (
            w.evidence_summary like concat('%', #{params.keyword}, '%')
            or fp.fire_point_name like concat('%', #{params.keyword}, '%')
            or s.sensor_code like concat('%', #{params.keyword}, '%')
            or g.imei like concat('%', #{params.keyword}, '%')
            or e.label_code like concat('%', #{params.keyword}, '%')
            or t.assignee_nick_name like concat('%', #{params.keyword}, '%')
        )

    ${params.dataScope}

order by case t.task_status
             when 'manual_pending' then 1
             when 'assigned' then 2
             when 'processing' then 3
             when 'waiting_external' then 4
             when 'verifying' then 5
             else 6
         end,
         coalesce(t.dispatch_time, t.create_time) desc,
         t.task_id desc

mapper.insert:
insert into fe_device_warning_task_record (
    task_id, warning_id, action_type, action_channel, action_description,
    next_task_status, operator_user_id, operator_user_name, operator_nick_name,
    action_time, create_by, create_time
) values (
    #{taskId}, #{warningId}, #{actionType}, #{actionChannel}, #{actionDescription},
    #{nextTaskStatus}, #{operatorUserId}, #{operatorUserName}, #{operatorNickName},
    #{actionTime}, #{createBy}, #{createTime}
)
